-- =====================================================================

INSERT IGNORE INTO `subcategories` (`category_id`, `name`, `name_en`, `slug`) SELECT c.`id`, 'Сумаризатори', 'Summarizers', 'summarizers' FROM `categories` c WHERE c.`slug` = 'text-chatbots' LIMIT 1;

SET @uid = (SELECT `id` FROM `users` WHERE `email` = 'whitevelvetelf@gmail.com' LIMIT 1);

-- Recall — Сумаризатори
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'recall.it' OR LOWER(`name`) = LOWER('Recall'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Recall', NULL, 'https://www.recall.it', NULL, NULL, 'AI-сумаризатор і особиста база знань: зберігає статті, відео й PDF, робить короткі підсумки, сам розкладає їх за тегами та нагадує повторити через квізи.', 'An AI summarizer and personal knowledge base: it saves articles, videos and PDFs, creates short summaries, organises them with tags and helps you review through quizzes.', 'Recall перетворює все, що ви читаєте й дивитеся, на впорядковану базу знань. Статті, відео та PDF зберігаються в один клік, AI робить підсумок, автоматично розставляє розумні теги та пов''язує нові матеріали з уже збереженими у візуальний граф знань. Можна спілкуватися з AI на основі власної бази, інтернету чи обох одразу, слухати матеріали в режимі озвучення, а квізи з інтервальним повторенням допомагають краще запам''ятати прочитане. Під час перегляду сайтів Recall підказує пов''язані нотатки. Сервісом користуються понад 700 000 людей. Тарифи: Free — 10 AI-підсумків на місяць; Plus — $10 на місяць при річній оплаті (необмежені підсумки, чат, озвучення, квізи); Max — $38 на місяць при річній оплаті (вибір моделі ChatGPT, Claude чи Gemini, особистий онбординг).', 'Recall turns everything you read and watch into an organised knowledge base. Articles, videos and PDFs are saved in one click, AI writes a summary, adds smart tags automatically and links new material to what you have already saved in a visual knowledge graph. You can chat with AI over your own knowledge base, the internet or both, listen to content with text-to-speech, and quizzes with spaced repetition help you remember what you read. While you browse, Recall surfaces related notes. More than 700,000 people use it. Plans: Free — 10 AI summaries a month; Plus — $10 a month billed yearly (unlimited summaries, chat, listen mode, quizzes); Max — $38 a month billed yearly (choice of ChatGPT, Claude or Gemini models, 1:1 onboarding).', 'Підсумки статей, відео й PDF в один клік
Автоматичні теги та граф знань
AI-чат з вашою базою та інтернетом
Квізи з інтервальним повторенням
Озвучення матеріалів', 'One-click summaries of articles, videos and PDFs
Automatic tags and a knowledge graph
AI chat with your knowledge base and the web
Quizzes with spaced repetition
Text-to-speech listen mode', 'Люди, які постійно навчаються: студенти, дослідники, фахівці, що читають і дивляться багато матеріалів.', 'Lifelong learners: students, researchers and professionals who read and watch a lot of material.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'recall.it' OR LOWER(`name`) = LOWER('Recall')) ORDER BY `id` LIMIT 1);
