INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Recall turns everything you read and watch into an organised knowledge base. Articles, videos and PDFs are saved in one click, AI writes a summary, adds smart tags automatically and links new material to what you have already saved in a visual knowledge graph. You can chat with AI over your own knowledge base, the internet or both, listen to content with text-to-speech, and quizzes with spaced repetition help you remember what you read. While you browse, Recall surfaces related notes. More than 700,000 people use it. Plans: Free — 10 AI summaries a month; Plus — $10 a month billed yearly (unlimited summaries, chat, listen mode, quizzes); Max — $38 a month billed yearly (choice of ChatGPT, Claude or Gemini models, 1:1 onboarding).', 'manual' FROM DUAL WHERE @new = 1;
