-- QuillBot — Сумаризатори
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'quillbot.com' OR LOWER(`name`) = LOWER('QuillBot'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'QuillBot', NULL, 'https://quillbot.com', NULL, NULL, 'Набір AI-інструментів для тексту: сумаризатор, перефразування, перевірка граматики, AI-детектор і «гуманізатор», перекладач та генератор цитувань.', 'A suite of AI writing tools: summarizer, paraphraser, grammar checker, AI detector and humanizer, translator and citation generator.', 'QuillBot — один з найпопулярніших онлайн-помічників для роботи з текстом. Сумаризатор скорочує статті та документи до ключових пунктів або короткого абзацу, перефразувальник переписує речення в різних стилях, а перевірка граматики виправляє помилки. Є AI-детектор, «гуманізатор» тексту, перевірка на плагіат, перекладач і генератор цитувань. Інструменти працюють у вебі та як розширення для Chrome. Базові функції безкоштовні з лімітами; Premium знімає обмеження й відкриває всі режими, при річній оплаті — від $4,17 на місяць (ціна може залежати від регіону).', 'QuillBot is one of the most popular online helpers for working with text. The summarizer condenses articles and documents into key points or a short paragraph, the paraphraser rewrites sentences in different styles, and the grammar checker fixes mistakes. There is also an AI detector, a text humanizer, a plagiarism checker, a translator and a citation generator. The tools work on the web and as a Chrome extension. Core features are free with limits; Premium removes the limits and unlocks all modes, from $4.17 a month billed annually (prices may vary by region).', 'Сумаризатор: ключові пункти чи абзац
Перефразування в різних стилях
Граматика, плагіат і AI-детектор
Переклад і генератор цитувань
Розширення для Chrome', 'Summarizer: key points or a paragraph
Paraphrasing in different styles
Grammar, plagiarism and AI detection
Translator and citation generator
Chrome extension', 'Студенти, автори й усі, хто пише англійською та хоче швидше працювати з текстами.', 'Students, writers and anyone who writes in English and wants to work with text faster.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
