-- Scholarcy — Сумаризатори
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'scholarcy.com' OR LOWER(`name`) = LOWER('Scholarcy'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Scholarcy', NULL, 'https://www.scholarcy.com', NULL, NULL, 'Сумаризатор наукових статей: перетворює дослідження на картки з ключовими висновками, допомагає вести нотатки, будувати матрицю літератури й бібліографію.', 'A research paper summarizer: it turns studies into flashcards with key findings and helps you take notes, build a literature matrix and bibliographies.', 'Scholarcy створено для тих, хто читає багато наукових текстів. Сервіс приймає статті у різних форматах і робить з них «картки-підсумки»: основні висновки, методи, результати, обмеження та посилання. Тексти можна виділяти, коментувати й редагувати, картки — групувати в колекції та експортувати, а з кількох статей — зібрати матрицю літератури для огляду. Бібліографія формується в один клік. Безкоштовна версія обмежена 10 підсумками; місячний план коштує $4,99 на місяць з тижневим безкоштовним періодом і дає необмежені розширені підсумки.', 'Scholarcy is built for people who read a lot of academic text. It takes papers in various formats and turns them into ''flashcard summaries'': key findings, methods, results, limitations and references. You can highlight, annotate and edit text, group flashcards into collections and export them, and build a literature matrix from several papers for a review. Bibliographies are generated in one click. The free version is limited to 10 summaries; the monthly plan costs $4.99 a month with a one-week free trial and gives unlimited enhanced summaries.', 'Картки-підсумки наукових статей
Нотатки, виділення й редагування тексту
Матриця літератури для оглядів
Бібліографія в один клік', 'Flashcard summaries of research papers
Notes, highlights and text editing
Literature matrix for reviews
One-click bibliographies', 'Студенти, магістранти й науковці, які готують огляди літератури.', 'Students, master''s students and researchers preparing literature reviews.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'scholarcy.com' OR LOWER(`name`) = LOWER('Scholarcy')) ORDER BY `id` LIMIT 1);
