INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Scholarcy is built for people who read a lot of academic text. It takes papers in various formats and turns them into ''flashcard summaries'': key findings, methods, results, limitations and references. You can highlight, annotate and edit text, group flashcards into collections and export them, and build a literature matrix from several papers for a review. Bibliographies are generated in one click. The free version is limited to 10 summaries; the monthly plan costs $4.99 a month with a one-week free trial and gives unlimited enhanced summaries.', 'manual' FROM DUAL WHERE @new = 1;
