-- Glasp — Сумаризатори
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'glasp.co' OR LOWER(`name`) = LOWER('Glasp'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Glasp', NULL, 'https://glasp.co', NULL, NULL, 'Розширення для виділення цитат на сайтах і AI-підсумків відео YouTube та PDF, з експортом у Notion і публічною бібліотекою виділень.', 'An extension for highlighting quotes on websites and creating AI summaries of YouTube videos and PDFs, with export to Notion and a public library of highlights.', 'Glasp — інструмент для тих, хто багато читає в інтернеті. Він дає змогу виділяти й коментувати текст на будь-якому сайті, зберігати виділення в особистій чи публічній бібліотеці та бачити, що виділяють інші читачі. AI робить підсумки відео YouTube, PDF-файлів і аудіозаписів, відстежує нові відео на обраних каналах і дає змогу спілкуватися з контентом сторінки чи відео. Виділення щодня синхронізуються з Notion. Безкоштовний план: 3 базові підсумки YouTube на день, 30 PDF, 30 хвилин аудіо на місяць; Pro — $15 на місяць або $150 на рік (необмежені базові підсумки, 1 000 розширених підсумків на місяць, приватні виділення).', 'Glasp is a tool for people who read a lot online. It lets you highlight and annotate text on any website, keep highlights in a personal or public library and see what other readers highlight. AI summarises YouTube videos, PDF files and audio recordings, tracks new videos on chosen channels and lets you chat with the content of a page or video. Highlights sync to Notion daily. The free plan includes 3 basic YouTube summaries a day, 30 PDFs and 30 minutes of audio a month; Pro costs $15 a month or $150 a year (unlimited basic summaries, 1,000 advanced summaries a month, private highlights).', 'Виділення й нотатки на будь-якому сайті
AI-підсумки YouTube, PDF і аудіо
Відстеження каналів YouTube
Синхронізація з Notion', 'Highlights and notes on any website
AI summaries of YouTube, PDFs and audio
YouTube channel tracking
Sync to Notion', 'Читачі, студенти й дослідники, які збирають цитати та нотатки з інтернету.', 'Readers, students and researchers who collect quotes and notes from the web.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
